examples.sql:
SET VARIABLE schema = '{
  "type":"object",
  "properties":{
    "retries":{"type":"integer","default":3}
  }
}';
SELECT json_schema_validate_schema(
  getvariable('schema'));
SELECT json_schema_update(
  getvariable('schema'), '{}');
-- {"retries":3}
SELECT json_schema_patch(
  getvariable('schema'), '{}');
